def run(rdap_json, rdap_text, now):
    from datetime import datetime, timezone
    import re

    def parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        s = s.strip().replace('Z', '+00:00')
        try:
            return datetime.fromisoformat(s)
        except Exception:
            pass
        for fmt in ('%Y-%m-%d', '%Y-%m-%dT%H:%M:%S%z', '%Y-%m-%dT%H:%M:%S'):
            try:
                return datetime.strptime(s[:len(fmt.replace('%z', ''))], fmt)
            except Exception:
                continue
        return None

    def find_dates(obj):
        created = None
        expires = None
        if isinstance(obj, dict):
            for k, v in obj.items():
                kl = str(k).lower()
                if created is None and kl in ('created', 'registration_date', 'eventdate') and isinstance(v, str):
                    created = v
                if expires is None and kl in ('expires', 'expiration', 'expiry') and isinstance(v, str):
                    expires = v
                c2, e2 = find_dates(v)
                if created is None and c2:
                    created = c2
                if expires is None and e2:
                    expires = e2
        elif isinstance(obj, list):
            for v in obj:
                c2, e2 = find_dates(v)
                if created is None and c2:
                    created = c2
                if expires is None and e2:
                    expires = e2
        return created, expires

    created, expires = find_dates(rdap_json)

    if not created and isinstance(rdap_text, str):
        m = re.search(r'(?i)created[^0-9]{0,20}([0-9]{4}-[0-9]{2}-[0-9]{2}[^\n<]*)', rdap_text)
        if m:
            created = m.group(1).strip()

    now_dt = parse_dt(now) or datetime.now(timezone.utc)
    if now_dt.tzinfo is None:
        now_dt = now_dt.replace(tzinfo=timezone.utc)
    created_dt = parse_dt(created)
    if created_dt and created_dt.tzinfo is None:
        created_dt = created_dt.replace(tzinfo=timezone.utc)
    expires_dt = parse_dt(expires)
    if expires_dt and expires_dt.tzinfo is None:
        expires_dt = expires_dt.replace(tzinfo=timezone.utc)

    domain_age_days = -1
    if created_dt:
        domain_age_days = max(0, int((now_dt - created_dt).total_seconds() // 86400))

    created_recently = bool(domain_age_days != -1 and domain_age_days < 180)
    return {
        'created': created or '',
        'expires': expires or '',
        'domain_age_days': domain_age_days,
        'created_recently': created_recently,
        'has_expiry': bool(expires_dt)
    }

def run(results, domain):
    results = results or []
    neg_words = ('scam', 'fraud', 'fake', 'complaint', 'ripoff', 'refund', 'chargeback', 'phishing', 'malware', 'spoof')
    pos_words = ('legit', 'trusted', 'official', 'safe', 'reputable', 'review', 'works')
    neg = pos = neu = 0
    notes = []
    dom = (domain or '').lower()
    for r in results[:10]:
        text = ' '.join([str(r.get('title', '')), str(r.get('content', ''))]).lower()
        score_neg = sum(1 for w in neg_words if w in text)
        score_pos = sum(1 for w in pos_words if w in text)
        if score_neg > score_pos:
            neg += 1
            notes.append(f"{r.get('title', '')}: negative")
        elif score_pos > score_neg:
            pos += 1
            notes.append(f"{r.get('title', '')}: positive")
        else:
            neu += 1
            if dom and dom in text:
                notes.append(f"{r.get('title', '')}: mentions domain")
    summary = f'{neg} negative, {pos} positive, {neu} neutral search results'
    return {'negative_count': neg, 'positive_count': pos, 'neutral_count': neu, 'summary': summary, 'notes': notes[:5]}

def run(domain, domain_age_days, created_recently, https_ok, https_error, search_negative, search_positive, search_neutral, search_notes):
    age = domain_age_days if isinstance(domain_age_days, int) else -1
    score = 0
    reasons = []

    if age < 0:
        score += 20
        reasons.append('RDAP age unavailable')
    elif age < 30:
        score += 35
        reasons.append('Domain is younger than 30 days')
    elif age < 180:
        score += 20
        reasons.append('Domain is younger than 6 months')
    elif age > 0:
        score -= 10
        reasons.append('Domain age is older than 6 months')

    status = https_ok if isinstance(https_ok, int) else 0
    if status == 0:
        score += 20
        reasons.append('HTTPS probe failed or site unreachable')
    elif 200 <= status < 400:
        score -= 10
        reasons.append('HTTPS loads successfully')
    else:
        score += 10
        reasons.append(f'HTTPS returned status {status}')

    neg = int(search_negative or 0)
    pos = int(search_positive or 0)
    if neg >= 3:
        score += 35
        reasons.append('Multiple negative search mentions')
    elif neg == 2:
        score += 25
        reasons.append('Several negative search mentions')
    elif neg == 1:
        score += 12
        reasons.append('Some negative search mentions')

    if pos >= 2 and neg == 0:
        score -= 10
        reasons.append('Search results are mostly positive')
    elif pos > neg:
        score -= 5
        reasons.append('Positive search signals outnumber negative ones')

    if created_recently:
        score += 10
        reasons.append('Domain appears recently created')

    if score < 0:
        score = 0
    if score > 100:
        score = 100

    if score >= 70:
        verdict = 'likely scam'
        escalate = False
    elif score >= 40:
        verdict = 'borderline'
        escalate = True
    else:
        verdict = 'likely not scam'
        escalate = False

    if search_notes:
        reasons.extend([n for n in (search_notes if isinstance(search_notes, list) else [str(search_notes)])[:3]])

    return {'score': score, 'verdict': verdict, 'reasons': reasons[:8], 'escalate': escalate, 'escalated': escalate}

def run(domain, domain_age_days, created_recently, https_ok, https_error, search_summary, risk_score, verdict, reasons, escalated, research_result):
    def age_phrase(days):
        if days in (None, -1):
            return 'an unknown age'
        try:
            days = int(days)
        except Exception:
            return 'an unknown age'
        if days < 45:
            return f'about {days} days old'
        years = days / 365.0
        if years < 1.5:
            months = max(1, round(days / 30.0))
            return f'about {months} months old'
        return f'about {round(years):d} years old'

    age_txt = age_phrase(domain_age_days)
    https_txt = 'works' if isinstance(https_ok, int) and 200 <= https_ok < 400 else 'failed'
    if verdict == 'likely scam':
        speech = f'{domain} looks likely scam with a risk score of {risk_score} out of 100. I would avoid it. The domain is {age_txt}, HTTPS {https_txt}, and search results suggest trouble.'
    elif verdict == 'borderline':
        if escalated and research_result:
            speech = f'{domain} looks borderline with a risk score of {risk_score} out of 100. The domain is {age_txt}, HTTPS {https_txt}, and search results are mixed. I have deeper research to review.'
        else:
            speech = f'{domain} looks borderline with a risk score of {risk_score} out of 100. The domain is {age_txt}, HTTPS {https_txt}, and search results are mixed. I could not complete the paid follow-up.'
    else:
        speech = f'{domain} looks likely not scam with a risk score of {risk_score} out of 100. The main checks look better than not. The domain is {age_txt}, HTTPS {https_txt}, and search results do not raise strong alarm.'

    report = f"""# Scam Sniffer Report

## Verdict
- **Domain:** {domain}
- **Classification:** {verdict}
- **Risk score:** {risk_score}/100
- **Domain age:** {age_txt}
- **HTTPS:** {https_txt}
- **Search summary:** {search_summary or 'No search data'}

## Reasons
"""
    for r in (reasons or [])[:8]:
        report += f'- {r}\n'
    if escalated and research_result:
        report += f"\n## Deeper Research\n\n{research_result}\n"
    return {'speech': speech[:900], 'report': report, 'speech_chars': len(speech[:900])}
